import React from 'react';

import { showModal } from '@ui-kit/Modal';

import ObstacleModal from './index';
import { IObstacle, ObstacleCategory, ObstacleType } from '../../@types/obstacles.types';

export interface IAddObstacleConstraints {
  type?: ObstacleType;
}

export function addObstacleModalAsync(constraints?: IAddObstacleConstraints): Promise<IObstacle> {
  return new Promise((resolve) => {
    showModal({
      title: 'Добавление локального препятствия или POI',
      size: 'lg',
      flush: true,
      children: (closeHandler: () => void) => (
        <ObstacleModal
          onAdd={(bp) => {
            resolve(bp);
            closeHandler();
          }}
          onCancel={closeHandler}
          data={{
            id: 0,
            name: '',
            description: '',
            category: ObstacleCategory.CategoryNo,
            type: ObstacleType.Poi,
            comment: '',
            created: { date: new Date(), id: 0, name: 'i' },
            updated: null,
            altitude: 0,
            coordinates: [0, 0],
            link: '',
            region: {
              id: 1067455,
              name: 'Пензенская область',
            },
          }}
          constraints={constraints}
        />
      ),
    });
  });
}

export function editObstacleModalAsync(m: IObstacle): Promise<IObstacle> {
  return new Promise((resolve) => {
    showModal({
      title: 'Редактирование локального препятствия или POI',
      size: 'lg',
      children: (closeHandler: () => void) => (
        <ObstacleModal
          data={m}
          onEdit={(bp) => {
            resolve(bp);
            closeHandler();
          }}
          onCancel={closeHandler}
        />
      ),
    });
  });
}
